// Every "thing" this workflow watches for new releases, one item each -
// ansible-core, the community `ansible` PyPI package, and each tracked
// collection. Adding a collection is a one-line addition here; nothing
// downstream needs to change (Normalize version / Get changelog excerpt /
// Combine current versions all branch on `kind`, and everything after that
// is already generic per-item).
//
// tagPrefix: most ansible-collections repos tag releases with the bare
// semver (matches the Galaxy version exactly, e.g. "13.4.0"), but a few
// prefix the git tag with "v" (e.g. google.cloud, cisco.ios -> "v1.14.0").
// Verified individually against the real GitHub tags before adding each
// collection here - getting this wrong just 404s the changelog fetch for
// that one collection (degrades to "no changelog excerpt", not a failure).
const collections = [
  ['community.general', ''],
  ['ansible.posix', ''],
  ['community.crypto', ''],
  ['kubernetes.core', ''],
  ['community.docker', ''],
  ['amazon.aws', ''],
  ['google.cloud', 'v'],
  ['community.mysql', ''],
  ['community.postgresql', ''],
  ['community.windows', ''],
  ['ansible.windows', ''],
  ['community.vmware', ''],
  ['cisco.ios', 'v'],
];

const targets = [
  { kind: 'ansible-core', key: 'ansible/ansible' },
  { kind: 'community-package', key: 'ansible (pypi package)' },
  ...collections.map(([fqcn, tagPrefix]) => {
    const [galaxyNamespace, galaxyName] = fqcn.split('.');
    return {
      kind: 'collection',
      key: fqcn,
      githubOwner: 'ansible-collections',
      githubRepo: fqcn,
      galaxyNamespace,
      galaxyName,
      tagPrefix,
    };
  }),
];

return targets.map(json => ({ json }));

// runOnceForEachItem - $json here is this item's response from "Get latest
// version" (GitHub release, PyPI JSON, or Galaxy collection metadata,
// depending on kind); the target descriptor that produced it comes from the
// paired item on "Target list", not from $json.
const target = $('Target list').item.json;
const resp = $json;

let version = null;
let release_name = '';
let url = '';

if (target.kind === 'ansible-core') {
  version = resp.tag_name || null;
  release_name = resp.name || resp.tag_name || '';
  url = resp.html_url || ('https://github.com/ansible/ansible/releases/tag/' + (resp.tag_name || ''));
} else if (target.kind === 'community-package') {
  version = (resp.info || {}).version || null;
  release_name = 'Ansible ' + (version || '');
  url = 'https://pypi.org/project/ansible/' + (version || '') + '/';
} else {
  // Galaxy, not GitHub Releases - some collections (e.g. kubernetes.core,
  // community.mysql) only tag releases on GitHub without creating a Release
  // object, so /releases/latest 404s for them even though they publish
  // normally. Galaxy's API is the one version source that works uniformly
  // for every collection regardless of that.
  version = (resp.highest_version || {}).version || null;
  release_name = target.key + ' ' + (version || '');
  url = 'https://galaxy.ansible.com/ui/repo/published/' + target.galaxyNamespace + '/' + target.galaxyName + '/';
}

return { json: { ...target, version, release_name, url } };

// runOnceForEachItem - $json here is this item's changelog file response
// (from "Get changelog excerpt"); the version/url/etc. from "Normalize
// version" comes via the paired item, same reasoning as there.
const target = $('Normalize version').item.json;
const changelogResp = $json;

// Neither GitHub's release body, PyPI's JSON API, nor Galaxy's collection
// metadata embed the actual list of changes - all three just point at (or
// omit entirely) a changelog file. Pull out just the section for this exact
// version (between its 'vX.Y.Z\n===...' heading and the next one, optionally
// cut off earlier at stopAtRe) so Claude has concrete items to summarize
// instead of writing generic filler. Same heading format everywhere here -
// ansible-core, ansible-build-data, and every ansible-collections repo all
// generate their changelog with antsibull-changelog.
function extractChangelogSection(resp, version, stopAtRe) {
  if (!resp || resp.message || !resp.content) return '';
  let text;
  try {
    text = Buffer.from(resp.content, 'base64').toString('utf-8');
  } catch (e) {
    return '';
  }
  version = String(version || '').replace(/^v/, '');
  if (!version) return '';
  const headingRe = new RegExp('^v' + version.replace(/\./g, '\\.') + '\\n=+\\n', 'm');
  const startMatch = headingRe.exec(text);
  if (!startMatch) return '';
  let rest = text.slice(startMatch.index + startMatch[0].length);
  const nextHeadingRe = /\nv[0-9]+\.[0-9]+\.[0-9]+\n=+\n/;
  const nextMatch = nextHeadingRe.exec(rest);
  let section = nextMatch ? rest.slice(0, nextMatch.index) : rest;
  if (stopAtRe) {
    const stopMatch = stopAtRe.exec(section);
    if (stopMatch) section = section.slice(0, stopMatch.index);
  }
  return section.trim().slice(0, 4000);
}

const changelogSection = extractChangelogSection(
  changelogResp,
  target.version,
  target.kind === 'community-package' ? /\nUnchanged Collections\n-+\n/ : null
);

let notes;
if (target.kind === 'ansible-core') {
  const releaseResp = $('Get latest version').item.json;
  const baseNotes = (releaseResp.body || '').slice(0, 2000);
  notes = changelogSection
    ? baseNotes + '\n\nSpecific changes in this exact version (from the versioned changelog file):\n' + changelogSection
    : baseNotes;
} else if (target.kind === 'community-package') {
  notes = changelogSection
    ? 'What actually changed in this exact community package version (from ansible-community/ansible-build-data):\n' + changelogSection
    : '(no changelog data available for this version - PyPI does not provide one inline, mention that and link to the release)';
} else {
  notes = changelogSection
    ? 'Specific changes in this exact version (from the collection\'s own changelog):\n' + changelogSection
    : '(no changelog excerpt available for this version - mention that and link to the release)';
}

return {
  json: {
    repo_key: target.key,
    source: target.kind,
    version: target.version,
    release_name: target.release_name,
    notes: notes.slice(0, 6000),
    url: target.url,
  },
};

// State file lives at automation/ansible-release-watch/state.json in the
// blog repo itself - no external DB needed, and every change to it is a
// visible git commit.
const stateResp = $('Get state file').first().json;
let state = {};
let stateSha = null;
if (stateResp && !stateResp.message && stateResp.content) {
  try {
    state = JSON.parse(Buffer.from(stateResp.content, 'base64').toString('utf-8'));
    stateSha = stateResp.sha || null;
  } catch (e) {
    state = {};
  }
}

const current = $('Combine current versions').all().map(i => i.json);
const changed = current.filter(c => c.version && state[c.repo_key] !== c.version);

return changed.map(c => ({ json: { ...c, previous_version: state[c.repo_key] || null, full_state: state, state_sha: stateSha } }));

