  messages: [
    { role: 'system', content: "IMPORTANTE - LINGUA: scrivi l'intero contenuto dell'output (title, description, tags, body_markdown) in INGLESE, non in italiano — il blog ansiblebyexample.com e' in lingua inglese, indipendentemente dalla lingua di queste istruzioni. Scrivi post per ansiblebyexample.com, il blog Ansible di Luca Berton, nello stile esatto dei suoi articoli esistenti su nuove versioni (es. "Ansible 14 Community Package RC1 - Whats New and How to Test"). Formato OBBLIGATORIO: un H1 col titolo, poi sezioni H2 tipo "Introduction", "Whats New" (con sotto-sezioni H3 se utile), un blocco ```bash``` con i comandi di installazione/verifica, ed eventualmente una tabella markdown se ci sono più componenti/collection coinvolte. Tono pratico e tecnico, terza persona, niente marketing. USA I DETTAGLI CONCRETI forniti sotto (voci di bugfix/changelog specifiche, nomi di moduli/plugin, numeri di issue/PR, checksum, dimensioni file) invece di scrivere paragrafi generici tipo 'e' una release di manutenzione, nessuna nuova funzionalita' prevista' - quel tipo di frase e' accettabile SOLO se le note fornite sono davvero vuote o generiche. Se le note contengono un elenco di bugfix, riportali (anche sinteticamente, in elenco puntato) invece di riassumerli in una frase vaga. Se si tratta del pacchetto community 'ansible' e le note elencano quali collection sono cambiate rispetto alla versione precedente, apri il corpo dell'articolo spiegando ESATTAMENTE quello (es: questa versione e' identica alla precedente tranne per il bump di una collection da una versione all'altra, e il bug specifico che quel bump risolve) PRIMA delle istruzioni di installazione - e' l'informazione che il lettore cerca per prima, esattamente come fanno i veri annunci di rilascio sul forum ufficiale Ansible. Se si tratta di una collection (es. community.general, kubernetes.core), apri il corpo dell'articolo dicendo chiaramente per QUALE collection e' questo aggiornamento e a cosa serve in una frase, dato che il lettore potrebbe non conoscerla. Rispondi SOLO con JSON valido, nessun altro testo, con questa forma esatta: {"title": string, "description": string (max 160 caratteri, per lo meta tag), "category": uno tra playbooks|modules|roles|inventory|troubleshooting|cloud|cloud-virtualization|security|networking|network|containers|windows|testing|basics|fundamentals|advanced|enterprise|collections|community|best-practices|getting-started|interviews|tools|news (per un annuncio di nuova versione, di solito la scelta giusta e news oppure collections se si tratta di una singola collection), "tags": array di 4-7 stringhe minuscole, "body_markdown": string (markdown del corpo, SENZA il front matter YAML e SENZA il titolo H1 iniziale visto che verranno aggiunti a parte). IMPORTANTE: rispondi SOLO con un oggetto JSON valido. Nessun preambolo, nessuna domanda di chiarimento, nessun blocco markdown, nessuna spiegazione fuori dal JSON. Se qualche informazione manca, fai una assunzione ragionevole e produci comunque JSON valido." },
    { role: 'user', content: 'Nuova versione rilevata.

Repo/pacchetto: ' + $json.repo_key + '
Versione nuova: ' + $json.version + '
Versione precedente conosciuta: ' + ($json.previous_version || 'nessuna (primo giro)') + '
URL release: ' + $json.url + '

Release notes / changelog (se disponibili):
' + ($json.notes || '(nessuna nota disponibile - PyPI non fornisce changelog inline, menzionalo e rimanda al link)') }
  ]
}) }}

parameters.jsCode:
// runOnceForEachItem - this runs once PER changed target (ansible/ansible,
// the pypi community package, or any of the tracked collections), not once
// for the whole batch. It used to default to "run once for all items" with
// $json / .first(), which silently collapsed every run down to just the
// first changed item and dropped the rest.
const src = $('Determine new versions').item.json;
const response = $json;

function getText(resp) {
  if (!resp) return '';
  // OpenAI-compatible shape (served by claude-bridge, not Anthropic's own API).
  return resp.choices?.[0]?.message?.content || '';
}

const text = getText(response);
if (!text) throw new Error('Claude returned no text: ' + (response?.error?.message || JSON.stringify(response).slice(0, 2000)));
const cleaned = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
const jsonStart = cleaned.indexOf('{');
const jsonEnd = cleaned.lastIndexOf('}');

// Claude's JSON often contains real (unescaped) newlines/tabs inside string
// values - e.g. a fenced code block or a paragraph break inside
// body_markdown - which is invalid per strict JSON (control characters must
// be escaped) even though it looks fine to a human. Walk the text tracking
// whether we're inside a quoted string (respecting backslash-escapes) and
// only escape control characters found there - untouched outside strings, so
// real JSON structural whitespace is unaffected.
function sanitizeJsonControlChars(str) {
  let inString = false;
  let escapedNext = false;
  let out = '';
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (!inString) {
      if (ch === '"') inString = true;
      out += ch;
      continue;
    }
    if (escapedNext) {
      out += ch;
      escapedNext = false;
      continue;
    }
    if (ch === '\\') {
      out += ch;
      escapedNext = true;
    } else if (ch === '"') {
      out += ch;
      inString = false;
    } else if (ch === '\n') {
      out += '\\n';
    } else if (ch === '\r') {
      out += '\\r';
    } else if (ch === '\t') {
      out += '\\t';
    } else {
      out += ch;
    }
  }
  return out;
}

const draft = JSON.parse(sanitizeJsonControlChars(cleaned.slice(jsonStart, jsonEnd + 1)));

const today = new Date().toISOString().slice(0, 10);
const title = String(draft.title || (src.release_name + ' Released')).trim();
const filename = title.replace(/[\\/:*?"<>|]/g, '') + '.md';

const frontmatter = [
  '---',
  'title: "' + title.replace(/"/g, '\\"') + '"',
  'description: "' + String(draft.description || '').replace(/"/g, '\\"') + '"',
  'author: "Luca Berton"',
  'date: "' + today + '"',
  'category: "' + (['playbooks', 'modules', 'roles', 'inventory', 'troubleshooting', 'cloud', 'cloud-virtualization', 'security', 'networking', 'network', 'containers', 'windows', 'testing', 'basics', 'fundamentals', 'advanced', 'enterprise', 'collections', 'community', 'best-practices', 'getting-started', 'interviews', 'tools', 'news'].includes(draft.category) ? draft.category : 'news') + '"',
  'tags:',
  ...(draft.tags || ['ansible', 'release']).map(t => '  - "' + String(t).replace(/"/g, '\\"') + '"'),
  '---',
].join('\n');

const body = '# ' + title + '\n\n' + String(draft.body_markdown || '');
const fullContent = frontmatter + '\n\n' + body;

const branchSlug = 'ansible-release-' + String(src.repo_key).replace(/[^a-z0-9]+/gi, '-').toLowerCase() + '-' + String(src.version).replace(/[^a-z0-9.]+/gi, '-').toLowerCase();

return { json: {
  filename,
  filePath: 'src/content/tutorials/' + filename,
  fileContentBase64: Buffer.from(fullContent, 'utf-8').toString('base64'),
  branch: branchSlug,
  prTitle: 'New post: ' + title,
  prBody: 'Auto-drafted by the Ansible release watch workflow.\n\nRepo/package: `' + src.repo_key + '`\nNew version: `' + src.version + '` (previous: `' + (src.previous_version || 'none') + '`)\nRelease: ' + src.url + '\n\n**Review before merging:**\n- [ ] fact-check the drafted content against the real release notes\n- [ ] add a thumbnail (falls back to the default one otherwise)\n- [ ] adjust tone/length as needed',
  repo_key: src.repo_key,
  version: src.version,
  full_state: src.full_state,
  state_sha: src.state_sha,
} };

// Default mode (runOnceForAllItems) - deliberately NOT per-item. Each changed
// target's own item carries the SAME full_state snapshot (read once, before
// any of them were processed) plus state_sha from that one read. Merging
// once here, after every branch/PR for this run has been created, means one
// single PUT to state.json with every version bump from this run applied
// together - instead of N separate per-item PUTs racing on the same file
// SHA (whichever wrote last would win and silently drop every other item's
// update). Only matters once more than one target can plausibly change on
// the same day, which is exactly what adding the collection list makes
// likely.
const items = $('Build post + branch').all().map(i => i.json);
if (items.length === 0) return [];

const merged = { ...(items[0].full_state || {}) };
for (const it of items) {
  merged[it.repo_key] = it.version;
}

return [{
  json: {
    stateJsonBase64: Buffer.from(JSON.stringify(merged, null, 2), 'utf-8').toString('base64'),
    state_sha: items[0].state_sha,
  },
}];
